import assert from 'node:assert/strict';
import { globalRegistry } from './providers/registry.ts';
import { handleMultiAgentChatRequest } from './handlers/multiAgentChat.ts';

const calls: any[] = [];
const provider = { id: 'repro', name: 'repro', type: 'openai' as const, supportsImages: () => false, async *executeChat(request: any) {
  calls.push(request);
  if (request.message === '@parent work') yield { type: 'tool_use' as const, toolName: 'delegate_task', toolInput: { agent_id: 'child', instructions: 'do child work' } };
  else if (request.message === 'do child work') yield { type: 'text' as const, content: 'child output' };
  else yield { type: 'text' as const, content: 'finished' };
  yield { type: 'done' as const };
}};
globalRegistry.registerProvider(provider);
for (const id of ['parent', 'child']) globalRegistry.registerAgent({ id, name: id, description: '', provider: 'repro' });
const response = await handleMultiAgentChatRequest({ req: { json: async () => ({ message: '@parent work', requestId: 'repro' }) }, var: { config: { debugMode: false } } } as any, new Map());
const stream = await response.text();
assert(calls.some(call => call.message === 'do child work'), `Child not invoked: ${stream}`);
assert(calls.some(call => call.message.includes('child output')), 'Result not returned to parent');
console.log('Delegation works');
